"""navera_lite/vehicle.py — vehicles, the wind triangle and battery endurance. Part of NAVERA Lite, the
course's teaching stack (mission 03). Written for the course; it is not NAVERA code.

Conventions (courses/_lib/CONVENTIONS.md):
  * angles in DEGREES at the interface (radians only inside math.sin / math.cos …);
  * headings and tracks clockwise from true north: 0 = north, 90 = east, in [0, 360);
  * vectors are (east, north) pairs in m/s;
  * a wind vector points where the air GOES (a weather report gives where it comes FROM);
  * the unit is at the end of every name: _mps (m/s), _deg, _s, _m, _wh, _w.
"""
import math

VEHICLES = {"drone": 30.0, "plane": 100.0, "boat": 20.0, "robot": 10.0}   # max speed (m/s) per vehicle type

G_MPS2 = 9.81                                                             # gravity (m/s²)


# from mission 03 — finished: read it, use it, do not change it
def heading_vector(heading_deg):
    """The unit vector (east, north) of a heading measured clockwise from north.

    heading_deg: a heading in degrees (any value: 370 is the same as 10).
    Returns a tuple (east, north) of two floats, of length 1.

    Example:  heading_vector(90)  ->  (1.0, 6.1e-17)   (east; 6.1e-17 is 0 up to rounding)
    """
    h = math.radians(heading_deg)
    return math.sin(h), math.cos(h)


# from mission 03 — finished: read it, use it, do not change it
def ground_velocity(airspeed_mps, heading_deg, wind_e=0.0, wind_n=0.0):
    """The velocity over the ground, (east, north) in m/s, of a vehicle flying through the air at
    airspeed_mps on the heading heading_deg (degrees, clockwise from north), in a wind (wind_e, wind_n)
    in m/s (where the air goes). Without wind, the ground velocity is the air velocity.

    Example:  ground_velocity(10.0, 90.0, 0.0, 3.0)  ->  (10.0, 3.0)
    """
    e, n = heading_vector(heading_deg)
    return airspeed_mps * e + wind_e, airspeed_mps * n + wind_n


# from mission 03 — finished: read it, use it, do not change it
def wind_components(track_deg, wind_e, wind_n):
    """Split a wind (wind_e, wind_n) in m/s into its component ALONG the track track_deg (degrees,
    clockwise from north) and its component ACROSS it.

    Returns (along_mps, cross_mps): along > 0 is a tailwind, < 0 a headwind; cross > 0 pushes the
    vehicle to the RIGHT of its track, < 0 to the left.

    Example:  wind_components(0.0, 2.0, -5.0)  ->  (-5.0, 2.0)   (track north: 5 m/s headwind, 2 m/s to the right)
    """
    te, tn = heading_vector(track_deg)                 # along the track
    re, rn = heading_vector(track_deg + 90.0)          # 90° to the right of it
    return wind_e * te + wind_n * tn, wind_e * re + wind_n * rn


# from mission 03 — finished: read it, use it, do not change it
def heading_for_track(track_deg, tas_mps, wind_e, wind_n):
    """The heading to fly so that the ground track is track_deg, and the ground speed along it.

    track_deg: wanted ground track (degrees, clockwise from north); tas_mps: true airspeed (m/s);
    (wind_e, wind_n): the wind in m/s (where the air goes).
    Returns (heading_deg, gs_mps), heading in [0, 360).
    Raises ValueError when no heading works: the crosswind is stronger than the airspeed, or the
    ground speed would not be positive (the wind pushes the vehicle backwards).

    Example:  heading_for_track(0.0, 10.0, 6.0, 0.0)  ->  (323.13, 8.0)   (crab 36.87° into the wind)
    """
    along, cross = wind_components(track_deg, wind_e, wind_n)
    if abs(cross) > tas_mps:
        raise ValueError(f"crosswind {abs(cross):.1f} m/s is stronger than the airspeed {tas_mps:.1f} m/s")
    crab_rad = math.asin(cross / tas_mps)
    gs = tas_mps * math.cos(crab_rad) + along
    if gs <= 0:
        raise ValueError(f"ground speed {gs:.1f} m/s: the headwind is stronger than the vehicle")
    return (track_deg - math.degrees(crab_rad)) % 360.0, gs


# from mission 03 — finished: read it, use it, do not change it
def endurance_s(battery_wh, power_w, reserve=0.2):
    """How long (s) a battery of battery_wh watt-hours lasts at power_w watts when the fraction
    `reserve` of it is never used (kept for landing).

    Raises ValueError if battery_wh <= 0, power_w <= 0, or reserve is not in [0, 1).

    Example:  endurance_s(50.0, 200.0, 0.1)  ->  810.0   (13.5 min)
    """
    if battery_wh <= 0:
        raise ValueError(f"battery_wh must be > 0, got {battery_wh}")
    if power_w <= 0:
        raise ValueError(f"power_w must be > 0, got {power_w}")
    if not 0.0 <= reserve < 1.0:
        raise ValueError(f"reserve must be in [0, 1), got {reserve}")
    return battery_wh * (1.0 - reserve) / power_w * 3600.0


# from mission 03 — finished: read it, use it, do not change it
class Vehicle:
    """A vehicle: a name, a cruise airspeed, a maximum speed, a battery and the power it draws in cruise."""

    # from mission 03 — finished: read it, use it, do not change it
    def __init__(self, name, cruise_mps, max_speed_mps, battery_wh, power_w):
        """Check the values and store them as attributes with the SAME names (self.name, self.cruise_mps,
        self.max_speed_mps, self.battery_wh, self.power_w).

        Raises ValueError if cruise_mps <= 0, or if max_speed_mps < cruise_mps (a vehicle cannot cruise
        faster than its maximum speed). Battery and power are checked by endurance_s() when it is used.

        Example:  Vehicle("rover", 2.0, 3.0, 400.0, 100.0).max_speed_mps  ->  3.0
        """
        if cruise_mps <= 0:
            raise ValueError(f"{name}: cruise_mps must be > 0, got {cruise_mps}")
        if max_speed_mps < cruise_mps:
            raise ValueError(f"{name}: max_speed_mps ({max_speed_mps}) must be >= cruise_mps ({cruise_mps})")
        self.name = name
        self.cruise_mps = cruise_mps
        self.max_speed_mps = max_speed_mps
        self.battery_wh = battery_wh
        self.power_w = power_w

    # from mission 03 — finished: read it, use it, do not change it
    def endurance_s(self, reserve=0.2):
        """Seconds of cruise flight of THIS vehicle (its own battery and cruise power), with the fraction
        `reserve` of the battery kept unused. Use the module function endurance_s() of TODO 5: do not
        write the formula twice.

        Example:  Vehicle("rover", 2.0, 3.0, 400.0, 100.0).endurance_s()  ->  11520.0
        """
        return endurance_s(self.battery_wh, self.power_w, reserve)

    # from mission 03 — finished: read it, use it, do not change it
    def range_m(self, wind_along_mps=0.0, reserve=0.2):
        """Distance (m) flown in a straight line at cruise airspeed until the usable battery is empty,
        with a wind component wind_along_mps along the path (> 0 tailwind, < 0 headwind).
        0.0 when the wind is so strong that the vehicle does not move forwards.

        Example:  Vehicle("rover", 2.0, 3.0, 400.0, 100.0).range_m(-0.5)  ->  17280.0
        """
        gs = self.cruise_mps + wind_along_mps
        if gs <= 0:
            return 0.0
        return gs * self.endurance_s(reserve)

    # from mission 03 — finished: read it, use it, do not change it
    def __repr__(self):
        # the text print() shows; {self.name!r} puts the name WITH its quotes, e.g. 'quad'
        return f"{type(self).__name__}({self.name!r}, cruise {self.cruise_mps} m/s)"


# from mission 03 — finished: read it, use it, do not change it
class Multirotor(Vehicle):
    """A multirotor (a "quad"). It IS a Vehicle: it inherits __init__, endurance_s(), range_m() and
    __repr__ from Vehicle, and adds one method of its own."""

    def hover_s(self, hover_power_w, reserve=0.2):
        """Seconds of hovering, when hovering draws hover_power_w watts (a multirotor's power is U-shaped in
        speed: hover often costs more than moderate forward flight, high speed more again)."""
        return endurance_s(self.battery_wh, hover_power_w, reserve)


# from mission 03 — finished: read it, use it, do not change it
class FixedWing(Vehicle):
    """A fixed-wing aircraft: it must fly faster than its stall speed, and it turns on a circle."""

    # from mission 03 — finished: read it, use it, do not change it
    def __init__(self, name, cruise_mps, max_speed_mps, battery_wh, power_w, stall_mps):
        """Build the Vehicle part with the parent class, then refuse a cruise speed that is not above
        the stall speed (ValueError), and store self.stall_mps.

        Example:  FixedWing("glider", 15.0, 25.0, 60.0, 80.0, 9.0).stall_mps  ->  9.0
                  FixedWing("glider", 15.0, 25.0, 60.0, 80.0, 9.0).endurance_s()  ->  2160.0
        """
        super().__init__(name, cruise_mps, max_speed_mps, battery_wh, power_w)
        if cruise_mps <= stall_mps:
            raise ValueError(f"{name}: cruise {cruise_mps} m/s is not above the stall speed {stall_mps} m/s")
        self.stall_mps = stall_mps

    # from mission 03 — finished: read it, use it, do not change it
    def turn_radius_m(self, bank_deg=30.0):
        """Radius (m) of a level turn at cruise speed with this bank angle (lab 03, Going further: Turn radius)."""
        return self.cruise_mps ** 2 / (G_MPS2 * math.tan(math.radians(bank_deg)))
